function Onboarding() {
  const [, setLocation] = useLocation(); const createProfile = useCreateProfile();
  const [step, setStep] = useState(1); const [saving, setSaving] = useState(false);
  const [form, setForm] = useState<ProfileInput>({ ...demoProfile }); 
  const update = (key: keyof ProfileInput, value: string | number | boolean) => setForm((prev) => ({ ...prev, [key]: value }));
  const finish = () => { setSaving(true); createProfile.mutate({ data: form }, { onSuccess: (profile) => { localStorage.setItem("kisanbiz-profile", JSON.stringify(profile)); setLocation("/dashboard"); }, onError: () => { localStorage.setItem("kisanbiz-profile", JSON.stringify({ ...form, id: form.id || "local-profile" })); setLocation("/dashboard"); } }); };
  return <div className="min-h-[100dvh] bg-background"><header className="flex items-center justify-between px-6 py-6 sm:px-12"><Brand /><Link href="/" className="text-sm font-semibold text-muted-foreground hover:text-foreground" data-testid="link-back-home">Save for later</Link></header><div className="mx-auto max-w-3xl px-6 pb-16 pt-8 sm:pt-16"><div className="mb-12 flex items-center justify-center gap-2">{[1,2,3].map((n) => <div key={n} className="flex items-center gap-2"><span className={`grid h-9 w-9 place-items-center rounded-full text-sm font-bold ${step >= n ? "bg-primary text-primary-foreground" : "border border-border text-muted-foreground"}`}>{step > n ? <Check size={16} /> : n}</span>{n < 3 && <span className={`h-px w-14 sm:w-24 ${step > n ? "bg-primary" : "bg-border"}`} />}</div>)}</div><div className="animate-rise"><p className="text-center text-[11px] font-bold uppercase tracking-[.2em] text-primary">Let’s make this useful</p><h1 className="mt-3 text-center font-display text-4xl sm:text-5xl">{step === 1 ? "Start with you." : step === 2 ? "Tell us about the work." : "A little context goes a long way."}</h1><p className="mx-auto mt-3 max-w-md text-center text-sm leading-6 text-muted-foreground">{step === 1 ? "This helps us make every answer feel closer to home." : step === 2 ? "No perfect answers. A rough estimate is enough to begin." : "We use this only to make your recommendations more relevant."}</p></div><div className="mt-10 rounded-3xl border border-border bg-card p-6 shadow-soft sm:p-10">{step === 1 && <div className="grid gap-5 sm:grid-cols-2"><Field label="Your name"><input value={form.name} onChange={(e) => update("name", e.target.value)} placeholder="e.g. Ramesh Patil" data-testid="input-profile-name" /></Field><Field label="Preferred language"><select value={form.language} onChange={(e) => update("language", e.target.value)} data-testid="select-language"><option>Marathi</option><option>Hindi</option><option>English</option></select></Field><Field label="State"><input value={form.state} onChange={(e) => update("state", e.target.value)} data-testid="input-profile-state" /></Field><Field label="District"><input value={form.district} onChange={(e) => update("district", e.target.value)} data-testid="input-profile-district" /></Field><Field label="Village / town" wide><input value={form.village} onChange={(e) => update("village", e.target.value)} data-testid="input-profile-village" /></Field></div>}{step === 2 && <div className="grid gap-5 sm:grid-cols-2"><Field label="What do you do today?" wide><select value={form.businessType} onChange={(e) => update("businessType", e.target.value)} data-testid="select-business-type"><option>Vegetable trading</option><option>Grocery shop</option><option>Dairy farming</option><option>Tailoring</option><option>Food processing</option><option>Other small business</option></select></Field><Field label="Money you can invest"><input type="number" value={form.capital} onChange={(e) => update("capital", Number(e.target.value))} data-testid="input-profile-capital" /></Field><Field label="Monthly business income"><input type="number" value={form.monthlyIncome} onChange={(e) => update("monthlyIncome", Number(e.target.value))} data-testid="input-profile-income" /></Field></div>}{step === 3 && <div className="space-y-6"><Field label="Years of experience"><input type="number" min="0" value={form.experienceYears} onChange={(e) => update("experienceYears", Number(e.target.value))} data-testid="input-profile-experience" /></Field><label className="flex cursor-pointer items-center justify-between rounded-2xl border border-border bg-muted/40 p-4"><div><p className="text-sm font-bold">Are you part of an SHG?</p><p className="mt-1 text-xs text-muted-foreground">This can unlock more relevant scheme matches.</p></div><input type="checkbox" checked={form.isShgMember} onChange={(e) => update("isShgMember", e.target.checked)} className="h-5 w-5 accent-[hsl(var(--primary))]" data-testid="checkbox-shg" /></label><div className="rounded-2xl bg-secondary p-4 text-sm leading-6"><span className="font-bold">Your privacy matters.</span> KisanBiz uses your answers to personalise guidance. You can change or remove them anytime.</div></div>}<div className="mt-9 flex justify-between gap-3"><button className="rounded-xl px-4 py-3 text-sm font-semibold text-muted-foreground hover:bg-muted disabled:opacity-30" onClick={() => setStep((s) => s - 1)} disabled={step === 1} data-testid="button-back-step">Back</button>{step < 3 ? <button className="inline-flex items-center gap-2 rounded-xl bg-primary px-6 py-3 text-sm font-bold text-primary-foreground" onClick={() => setStep((s) => s + 1)} data-testid="button-next-step">Continue <ArrowRight size={16} /></button> : <button className="inline-flex items-center gap-2 rounded-xl bg-primary px-6 py-3 text-sm font-bold text-primary-foreground disabled:opacity-60" onClick={finish} disabled={saving} data-testid="button-finish-profile">{saving ? "Saving..." : "Open my workspace"} <ArrowRight size={16} /></button>}</div></div></div></div>;
}

function Field({ label, wide, children }: { label: string; wide?: boolean; children: ReactNode }) { return <label className={`block ${wide ? "sm:col-span-2" : ""}`}><span className="mb-2 block text-xs font-bold uppercase tracking-wider text-muted-foreground">{label}</span>{children}</label>; }
const inputClass = "w-full rounded-xl border border-input bg-background px-3.5 py-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15";

function Dashboard() {
  const profile = readProfile(); const params = { userId: profile.id };
  const query = useGetInsights(params, { query: { queryKey: getGetInsightsQueryKey(params), enabled: Boolean(profile.id) } });
  const insights = query.data || fallbackInsights;
  return <><PageTitle eyebrow={`${profile.village}, ${profile.state} · ${insights.season}`} title={`Good morning, ${profile.name.split(" ")[0]}.`} description="Here’s what deserves your attention today." action={<Link href="/advisor" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground" data-testid="link-ask-dashboard"><MessageCircle size={16} /> Ask advisor</Link>} />{query.isError && <div className="mb-6"><ErrorNotice retry={() => query.refetch()} /></div>}<div className="grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><Card className="animate-rise delay-1 overflow-hidden bg-primary text-primary-foreground"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-primary-foreground/60">Seasonal context</p><h2 className="mt-2 font-display text-3xl">Rain is on the way.</h2><p className="mt-2 max-w-md text-sm leading-6 text-primary-foreground/75">A good week to protect stored produce and check which crops are moving fastest at the mandi.</p></div><span className="grid h-11 w-11 place-items-center rounded-2xl bg-primary-foreground/10"><CloudRain size={22} /></span></div><div className="mt-7 flex flex-wrap gap-2">{["Cover stored stock", "Check onion prices", "Plan transport"].map((tip) => <span key={tip} className="rounded-full bg-primary-foreground/10 px-3 py-1.5 text-xs">{tip}</span>)}</div></Card><Card className="animate-rise delay-2"><SectionHeading icon={Sun} title="Local weather" meta="Nashik" /><div className="flex items-end justify-between"><div><span className="font-display text-5xl">{insights.weather.temperature}°</span><p className="mt-1 text-sm text-muted-foreground">{insights.weather.condition}</p></div><div className="text-right text-xs text-muted-foreground"><p>Humidity <strong className="text-foreground">{insights.weather.humidity}%</strong></p><p className="mt-1">Rain chance <strong className="text-foreground">{insights.weather.forecast[0]?.rain}%</strong></p></div></div><div className="mt-6 flex justify-between border-t border-border pt-4">{insights.weather.forecast.slice(0, 4).map((day) => <div key={day.day} className="text-center"><p className="text-[10px] text-muted-foreground">{day.day}</p><p className="mt-1 text-xs font-bold">{day.high}°</p><div className="mx-auto mt-2 h-1 w-8 rounded-full bg-accent" /></div>)}</div></Card></div><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_1fr_.9fr]"><Card className="animate-rise delay-2"><SectionHeading icon={TrendingUp} title="Mandi prices" meta="Updated today" /><div className="space-y-1">{insights.prices.map((price) => <div key={price.commodity} className="flex items-center justify-between rounded-xl px-2 py-3 hover:bg-muted" data-testid={`row-price-${price.commodity.toLowerCase().replaceAll(" ", "-")}`}><div><p className="text-sm font-semibold">{price.commodity}</p><p className="text-xs text-muted-foreground">per {price.unit}</p></div><div className="text-right"><p className="font-bold">{money(price.modalPrice)}</p><p className={`flex items-center justify-end gap-1 text-xs ${price.trend === "up" ? "text-primary" : price.trend === "down" ? "text-destructive" : "text-muted-foreground"}`}>{price.trend === "up" ? <TrendingUp size={12} /> : price.trend === "down" ? <TrendingDown size={12} /> : null}{price.trend}</p></div></div>)}</div><Link href="/ideas" className="mt-3 flex items-center justify-end gap-1 text-xs font-bold text-primary" data-testid="link-market-ideas">Use this for ideas <ArrowRight size={13} /></Link></Card><Card className="animate-rise delay-3"><SectionHeading icon={Lightbulb} title="Today’s nudge" meta="From your advisor" /><div className="rounded-2xl bg-secondary p-4"><p className="font-display text-2xl leading-tight">“Small savings are also business capital.”</p><p className="mt-3 text-sm leading-6 text-muted-foreground">{insights.tips[2]}</p></div><Link href="/advisor" className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-primary" data-testid="link-nudge-advisor">Ask why <ArrowRight size={13} /></Link></Card><ReadinessMini /></div></>;
}

function ReadinessMini() { const profile = readProfile(); const params = { userId: profile.id }; const query = useGetReadiness(params, { query: { queryKey: getGetReadinessQueryKey(params), enabled: Boolean(profile.id) } }); const r = query.data || fallbackReadiness; return <Card className="animate-rise delay-4"><SectionHeading icon={Gauge} title="Bank readiness" meta="Your snapshot" /><div className="flex items-center gap-4"><div className="relative grid h-24 w-24 shrink-0 place-items-center rounded-full" style={{ background: `conic-gradient(hsl(var(--primary)) ${r.score * 3.6}deg, hsl(var(--muted)) 0deg)` }}><div className="grid h-[74px] w-[74px] place-items-center rounded-full bg-card"><span className="font-display text-3xl">{r.score}</span></div></div><div><p className="font-bold">{r.label}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">A few records today make tomorrow’s funding easier.</p></div></div><Link href="/readiness" className="mt-5 flex items-center justify-between rounded-xl bg-muted px-3 py-2.5 text-xs font-bold" data-testid="link-readiness-mini">See what to improve <ArrowRight size={14} /></Link></Card>; }

function AdvisorLegacy() {
  const profile = readProfile(); const send = useSendChat(); const [message, setMessage] = useState(""); const [listening, setListening] = useState(false);
  const [chat, setChat] = useState<{ role: "assistant" | "user"; content: string }[]>([{ role: "assistant", content: `Namaskar ${profile.name.split(" ")[0]}. I’m here to make the next business decision simpler. What are you thinking about today?` }]);
  const suggestions = ["Is this a good week to buy more onion?", "How much loan can my business handle?", "What can I start with ₹50,000?"];
  const ask = (text = message) => { if (!text.trim()) return; const next = [...chat, { role: "user" as const, content: text }]; setChat(next); setMessage(""); send.mutate({ data: { userId: profile.id, message: text, history: next } }, { onSuccess: (reply) => setChat((old) => [...old, { role: "assistant", content: reply.reply }]), onError: () => setChat((old) => [...old, { role: "assistant", content: "Based on what I know about your business, start with the smallest test you can afford. Track the result for two weeks, then decide whether to invest more. I can help you make a simple plan for it." }]) }); };
  return <><PageTitle eyebrow="Your local business companion" title="Ask, don’t overthink." description="Use everyday language. I’ll bring the numbers and explain the why." /><div className="grid gap-5 lg:grid-cols-[1fr_300px]"><Card className="flex min-h-[560px] flex-col p-0"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><Sparkles size={17} /></span><div><p className="text-sm font-bold">KisanBiz advisor</p><p className="text-[11px] text-muted-foreground"><span className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-primary" /> Ready to help</p></div></div><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted" data-testid="button-chat-more"><MoreHorizontal size={18} /></button></div><div className="flex-1 space-y-5 overflow-auto p-5">{chat.map((item, i) => <div key={`${item.role}-${i}`} className={`flex gap-3 ${item.role === "user" ? "flex-row-reverse" : ""}`} data-testid={`message-${item.role}-${i}`}><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold ${item.role === "user" ? "bg-accent text-foreground" : "bg-primary text-primary-foreground"}`}>{item.role === "user" ? initials(profile.name) : <Leaf size={15} />}</span><div className={`max-w-[78%] rounded-2xl px-4 py-3 text-sm leading-6 ${item.role === "user" ? "rounded-tr-sm bg-secondary" : "rounded-tl-sm bg-muted"}`}>{item.content}</div></div>)}{send.isPending && <div className="flex items-center gap-2 text-xs text-muted-foreground"><span className="h-2 w-2 animate-pulse rounded-full bg-primary" /><span className="h-2 w-2 animate-pulse rounded-full bg-primary [animation-delay:.15s]" /><span className="h-2 w-2 animate-pulse rounded-full bg-primary [animation-delay:.3s]" /> Thinking through it</div>}</div><div className="border-t border-border p-4"><div className="flex items-center gap-2 rounded-xl border border-input bg-background px-3 py-2 focus-within:border-primary"><input className="min-w-0 flex-1 bg-transparent px-1 py-2 text-sm outline-none" value={message} onChange={(e) => setMessage(e.target.value)} onKeyDown={(e) => e.key === "Enter" && ask()} placeholder="Ask about your business..." data-testid="input-chat-message" /><button onClick={() => setListening(!listening)} className={`rounded-lg p-2 ${listening ? "bg-accent text-foreground" : "text-muted-foreground hover:bg-muted"}`} data-testid="button-voice"><Mic size={17} /></button><button onClick={() => ask()} className="grid h-9 w-9 place-items-center rounded-lg bg-primary text-primary-foreground disabled:opacity-40" disabled={!message.trim() || send.isPending} data-testid="button-send-chat"><Send size={16} /></button></div><p className="mt-2 text-center text-[10px] text-muted-foreground">{listening ? "Listening for your question…" : "Try speaking naturally. There are no wrong questions."}</p></div></Card><div className="space-y-5"><Card><SectionHeading icon={Lightbulb} title="Try asking" /><div className="space-y-2">{suggestions.map((suggestion) => <button key={suggestion} onClick={() => ask(suggestion)} className="group w-full rounded-xl border border-border p-3 text-left text-xs leading-5 hover:border-primary hover:bg-secondary" data-testid={`button-suggestion-${suggestion.slice(0, 8)}`}><span>{suggestion}</span><ArrowRight size={13} className="mt-1 text-primary opacity-0 transition group-hover:opacity-100" /></button>)}</div></Card><div className="rounded-2xl bg-secondary p-5"><div className="flex items-center gap-2 text-primary"><ShieldCheck size={16} /><span className="text-xs font-bold">Advice with context</span></div><p className="mt-3 text-xs leading-5 text-muted-foreground">Your questions are answered using your profile, local market context and plain-language explanations.</p></div></div></div></>;
}

type SpeechRecognitionLike = {
  lang: string;
  interimResults: boolean;
  maxAlternatives: number;
  onresult: ((event: { results: ArrayLike<ArrayLike<{ transcript: string }>> }) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
};

function Advisor() {
  const profile = readProfile();
  const send = useSendChat();
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const [message, setMessage] = useState("");
  const [listening, setListening] = useState(false);
  const [chat, setChat] = useState<{ role: "assistant" | "user"; content: string }[]>([
    { role: "assistant", content: `Namaskar ${profile.name.split(" ")[0]}. I’m here to make the next business decision simpler. What are you thinking about today?` },
  ]);
  const suggestions = ["Is this a good week to buy more onion?", "How much loan can my business handle?", "What can I start with ₹50,000?"];
  const speak = (text: string) => {
    if (!("speechSynthesis" in window)) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = profile.language === "Hindi" ? "hi-IN" : profile.language === "Marathi" ? "mr-IN" : "en-IN";
    window.speechSynthesis.speak(utterance);
  };
  const toggleListening = () => {
    if (listening) {
      recognitionRef.current?.stop();
      setListening(false);
      return;
    }
    const speechWindow = window as unknown as { SpeechRecognition?: new () => SpeechRecognitionLike; webkitSpeechRecognition?: new () => SpeechRecognitionLike };
    const Recognition = speechWindow.SpeechRecognition ?? speechWindow.webkitSpeechRecognition;
    if (!Recognition) return;
    const recognition = new Recognition();
    recognition.lang = profile.language === "Hindi" ? "hi-IN" : profile.language === "Marathi" ? "mr-IN" : "en-IN";
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = (event) => {
      const transcript = event.results[0]?.[0]?.transcript;
      if (transcript) setMessage(transcript);
    };
    recognition.onend = () => setListening(false);
    recognitionRef.current = recognition;
    setListening(true);
    recognition.start();
  };
  const ask = (text = message) => {
    if (!text.trim()) return;
    const next = [...chat, { role: "user" as const, content: text }];
    setChat(next);
    setMessage("");
    send.mutate({ data: { userId: profile.id, message: text, history: next } }, {
      onSuccess: (reply) => setChat((old) => [...old, { role: "assistant", content: reply.reply }]),
      onError: () => setChat((old) => [...old, { role: "assistant", content: "Based on what I know about your business, start with the smallest test you can afford. Track the result for two weeks, then decide whether to invest more." }]),
    });
  };
  return <><PageTitle eyebrow="Your local business companion" title="Ask, don’t overthink." description="Use everyday language. I’ll bring the numbers and explain the why." /><div className="grid gap-5 lg:grid-cols-[1fr_300px]"><Card className="flex min-h-[560px] flex-col p-0"><div className="flex items-center gap-3 border-b border-border px-5 py-4"><span className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><Sparkles size={17} /></span><div><p className="text-sm font-bold">KisanBiz advisor</p><p className="text-[11px] text-muted-foreground"><span className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-primary" /> Ready to help</p></div></div><div className="flex-1 space-y-5 overflow-auto p-5">{chat.map((item, i) => <div key={`${item.role}-${i}`} className={`flex gap-3 ${item.role === "user" ? "flex-row-reverse" : ""}`}><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold ${item.role === "user" ? "bg-accent text-foreground" : "bg-primary text-primary-foreground"}`}>{item.role === "user" ? initials(profile.name) : <Leaf size={15} />}</span><div className={`flex max-w-[78%] items-end gap-2 rounded-2xl px-4 py-3 text-sm leading-6 ${item.role === "user" ? "rounded-tr-sm bg-secondary" : "rounded-tl-sm bg-muted"}`}><span>{item.content}</span>{item.role === "assistant" && <button onClick={() => speak(item.content)} className="shrink-0 rounded-md p-1 text-muted-foreground hover:bg-card hover:text-primary" aria-label="Read answer aloud" data-testid={`button-speak-${i}`}><Volume2 size={14} /></button>}</div></div>)}{send.isPending && <div className="flex items-center gap-2 text-xs text-muted-foreground"><span className="h-2 w-2 animate-pulse rounded-full bg-primary" /><span className="h-2 w-2 animate-pulse rounded-full bg-primary [animation-delay:.15s]" /><span className="h-2 w-2 animate-pulse rounded-full bg-primary [animation-delay:.3s]" /> Thinking through it</div>}</div><div className="border-t border-border p-4"><div className="flex items-center gap-2 rounded-xl border border-input bg-background px-3 py-2 focus-within:border-primary"><input className="min-w-0 flex-1 bg-transparent px-1 py-2 text-sm outline-none" value={message} onChange={(e) => setMessage(e.target.value)} onKeyDown={(e) => e.key === "Enter" && ask()} placeholder="Ask about your business..." data-testid="input-chat-message" /><button onClick={toggleListening} className={`rounded-lg p-2 ${listening ? "bg-accent text-foreground" : "text-muted-foreground hover:bg-muted"}`} aria-label="Speak your question" data-testid="button-voice"><Mic size={17} /></button><button onClick={() => ask()} className="grid h-9 w-9 place-items-center rounded-lg bg-primary text-primary-foreground disabled:opacity-40" disabled={!message.trim() || send.isPending} data-testid="button-send-chat"><Send size={16} /></button></div><p className="mt-2 text-center text-[10px] text-muted-foreground">{listening ? "Listening for your question…" : "Tap the mic to speak, or type naturally."}</p></div></Card><div className="space-y-5"><Card><SectionHeading icon={Lightbulb} title="Try asking" /><div className="space-y-2">{suggestions.map((suggestion) => <button key={suggestion} onClick={() => ask(suggestion)} className="group w-full rounded-xl border border-border p-3 text-left text-xs leading-5 hover:border-primary hover:bg-secondary" data-testid={`button-suggestion-${suggestion.slice(0, 8)}`}><span>{suggestion}</span><ArrowRight size={13} className="mt-1 text-primary opacity-0 transition group-hover:opacity-100" /></button>)}</div></Card><div className="rounded-2xl bg-secondary p-5"><div className="flex items-center gap-2 text-primary"><ShieldCheck size={16} /><span className="text-xs font-bold">Advice with context</span></div><p className="mt-3 text-xs leading-5 text-muted-foreground">Your questions are answered using your profile, local market context and plain-language explanations.</p></div></div></div></>;
}

function Ideas() {
  const profile = readProfile(); const recommend = useRecommendIdeas(); const [ideas, setIdeas] = useState<BusinessIdea[]>(fallbackIdeas); const [filter, setFilter] = useState("All");
  const run = () => recommend.mutate({ data: { capital: profile.capital, skills: profile.businessType, villageType: "Agricultural village", season: "Kharif" } }, { onSuccess: (data) => setIdeas(data.length ? data : fallbackIdeas), onError: () => setIdeas(fallbackIdeas) });
  const filtered = filter === "All" ? ideas : ideas.filter((idea) => idea.risk === filter);
  return <><PageTitle eyebrow="Find your next income stream" title="Ideas that fit your ground." description={`Ranked for ${profile.village}, your ₹${profile.capital.toLocaleString("en-IN")} capital and your experience in ${profile.businessType.toLowerCase()}.`} action={<button onClick={run} className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-3 text-sm font-bold hover:bg-muted" data-testid="button-refresh-ideas"><RefreshCw size={16} className={recommend.isPending ? "animate-spin" : ""} /> Refresh recommendations</button>} /><div className="mb-5 flex items-center gap-2 overflow-x-auto">{["All", "Low", "Medium", "High"].map((item) => <button key={item} onClick={() => setFilter(item)} className={`rounded-full px-4 py-2 text-xs font-bold ${filter === item ? "bg-primary text-primary-foreground" : "border border-border bg-card text-muted-foreground"}`} data-testid={`button-filter-${item.toLowerCase()}`}>{item === "All" ? "All ideas" : `${item} risk`}</button>)}</div><div className="space-y-4">{filtered.map((idea, index) => <Card key={idea.id} className={`animate-rise delay-${Math.min(index + 1, 4)} p-0`} data-testid={`card-idea-${idea.id}`}><div className="grid gap-5 p-5 sm:grid-cols-[58px_1fr_auto] sm:items-start sm:p-6"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><span className="font-display text-xl">{String(index + 1).padStart(2, "0")}</span></div><div><div className="flex flex-wrap items-center gap-2"><h2 className="font-display text-2xl">{idea.name}</h2><span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider text-primary">{idea.category}</span></div><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{idea.description}</p><div className="mt-4 flex flex-wrap gap-2 text-xs"><span className="rounded-lg bg-muted px-3 py-2"><strong className="text-foreground">{idea.startupCost}</strong> start-up</span><span className="rounded-lg bg-muted px-3 py-2"><strong className="text-foreground">{idea.profitRange}</strong> potential</span><span className={`rounded-lg px-3 py-2 ${idea.risk === "Low" ? "bg-[hsl(88_35%_90%)] text-primary" : "bg-accent/30 text-foreground"}`}>{idea.risk} risk</span></div><p className="mt-4 text-xs"><span className="font-bold text-primary">Why it fits: </span><span className="text-muted-foreground">{idea.whyItFits}</span></p></div><div className="flex items-center justify-between gap-6 sm:block sm:text-right"><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Demand</p><p className="mt-1 font-display text-3xl text-primary">{idea.demandScore}<span className="text-sm text-muted-foreground">/100</span></p></div><Link href="/plan" className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-primary" data-testid={`link-plan-${idea.id}`}>Build a plan <ArrowRight size={13} /></Link></div></div></Card>)}</div></>;
}

function defaultPlan(profile: Profile): FinancialPlan { const loan = Math.max(0, 120000 - profile.capital); return { emi: Math.round(loan / 24 * 1.12), breakEvenUnits: 84, breakEvenMonths: 8, dscr: 1.72, fundingMix: { ownCapital: profile.capital, termLoan: loan, workingCapital: 24000, subsidy: 18000 }, cashFlow: [{ month: "M1", revenue: 32000, expenses: 24500, cumulative: 7500 }, { month: "M2", revenue: 36500, expenses: 25200, cumulative: 18800 }, { month: "M3", revenue: 41000, expenses: 26800, cumulative: 33000 }, { month: "M4", revenue: 43800, expenses: 27400, cumulative: 49400 }, { month: "M5", revenue: 46200, expenses: 28100, cumulative: 67500 }, { month: "M6", revenue: 48000, expenses: 28900, cumulative: 86600 }], riskFlag: "Comfortable if monthly sales stay above ₹34,000." }; }

function Plan() {
  const profile = readProfile(); const calculate = useCalculatePlan(); const explain = useExplainPlan(); const [plan, setPlan] = useState<FinancialPlan>(() => defaultPlan(profile)); const [explanation, setExplanation] = useState("Your plan keeps the loan modest against your own capital. The first priority is to build a two-month expense buffer before adding another monthly payment."); const [form, setForm] = useState({ businessType: profile.businessType, startupCost: 120000, ownCapital: profile.capital, monthlyRevenue: 42000, monthlyExpenses: 28000, interestRate: 12, tenureMonths: 24 });
  const update = (key: keyof typeof form, value: string) => setForm((old) => ({ ...old, [key]: key === "businessType" ? value : Number(value) }));
  const calculateIt = () => calculate.mutate({ data: form }, { onSuccess: (value) => setPlan(value), onError: () => setPlan(defaultPlan(profile)) });
  const explainIt = () => explain.mutate({ data: { plan, language: profile.language } }, { onSuccess: (value) => setExplanation(value.explanation), onError: () => setExplanation("Your EMI is manageable when you keep at least ₹14,000 free after monthly expenses. Keep a buffer for weaker mandi weeks and use subsidy support before taking a larger loan.") });
  return <><PageTitle eyebrow="Make the numbers feel simple" title="A plan you can stand behind." description="Change the assumptions. See the funding mix, monthly commitment and the moment your business can pay for itself." action={<button onClick={() => window.print()} className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-3 text-sm font-bold hover:bg-muted" data-testid="button-download-plan"><Download size={16} /> Download / print</button>} /><div className="grid gap-5 xl:grid-cols-[350px_1fr]"><Card className="animate-rise"><SectionHeading icon={Pencil} title="Your assumptions" meta="Editable" /><div className="space-y-4"><Field label="Business type"><select value={form.businessType} onChange={(e) => update("businessType", e.target.value)} className={inputClass} data-testid="select-plan-business"><option>Vegetable trading</option><option>Food processing</option><option>Grocery shop</option><option>Dairy farming</option></select></Field><Field label="Total start-up cost"><input className={inputClass} type="number" value={form.startupCost} onChange={(e) => update("startupCost", e.target.value)} data-testid="input-plan-startup" /></Field><Field label="Your own capital"><input className={inputClass} type="number" value={form.ownCapital} onChange={(e) => update("ownCapital", e.target.value)} data-testid="input-plan-capital" /></Field><div className="grid grid-cols-2 gap-3"><Field label="Monthly sales"><input className={inputClass} type="number" value={form.monthlyRevenue} onChange={(e) => update("monthlyRevenue", e.target.value)} data-testid="input-plan-revenue" /></Field><Field label="Monthly costs"><input className={inputClass} type="number" value={form.monthlyExpenses} onChange={(e) => update("monthlyExpenses", e.target.value)} data-testid="input-plan-expenses" /></Field></div><div className="grid grid-cols-2 gap-3"><Field label="Interest %"><input className={inputClass} type="number" value={form.interestRate} onChange={(e) => update("interestRate", e.target.value)} data-testid="input-plan-interest" /></Field><Field label="Tenure months"><input className={inputClass} type="number" value={form.tenureMonths} onChange={(e) => update("tenureMonths", e.target.value)} data-testid="input-plan-tenure" /></Field></div><button onClick={calculateIt} disabled={calculate.isPending} className="mt-2 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground disabled:opacity-60" data-testid="button-calculate-plan">{calculate.isPending ? "Calculating..." : "Recalculate plan"} <ArrowRight size={15} /></button></div></Card><div className="space-y-5"><div className="grid gap-4 sm:grid-cols-3"><Metric label="Monthly EMI" value={money(plan.emi)} note="estimated" icon={CreditCard} /><Metric label="Break-even" value={`${plan.breakEvenMonths} months`} note={`${plan.breakEvenUnits} units / month`} icon={TrendingUp} /><Metric label="DSCR" value={plan.dscr.toFixed(2)} note="repayment comfort" icon={ShieldCheck} /></div><Card className="animate-rise delay-2"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><SectionHeading icon={BarChart3} title="Funding mix" meta="How the start-up is funded" /><span className="rounded-full bg-[hsl(88_35%_90%)] px-3 py-1.5 text-xs font-bold text-primary">{plan.riskFlag.startsWith("Comfortable") ? "Healthy plan" : "Review this plan"}</span></div><div className="mt-2 flex h-4 overflow-hidden rounded-full bg-muted"><div className="bg-primary" style={{ width: `${Math.min(100, plan.fundingMix.ownCapital / form.startupCost * 100)}%` }} /><div className="bg-accent" style={{ width: `${Math.min(100, plan.fundingMix.termLoan / form.startupCost * 100)}%` }} /><div className="bg-[#8bb3a0]" style={{ width: `${Math.min(100, plan.fundingMix.subsidy / form.startupCost * 100)}%` }} /></div><div className="mt-5 grid gap-3 sm:grid-cols-4">{[["Your capital", plan.fundingMix.ownCapital, "bg-primary"], ["Term loan", plan.fundingMix.termLoan, "bg-accent"], ["Working capital", plan.fundingMix.workingCapital, "bg-[#8bb3a0]"], ["Subsidy", plan.fundingMix.subsidy, "bg-muted-foreground"]].map(([label, value, color]) => <div key={String(label)} className="flex items-center gap-2"><span className={`h-2.5 w-2.5 rounded-full ${color}`} /><div><p className="text-[11px] text-muted-foreground">{label}</p><p className="text-sm font-bold">{money(Number(value))}</p></div></div>)}</div></Card><Card className="animate-rise delay-3"><SectionHeading icon={BarChart3} title="Cash flow" meta="First six months" /><div className="flex h-40 items-end gap-2 border-b border-border pb-2 sm:gap-5">{plan.cashFlow.map((month) => <div key={month.month} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="w-full max-w-10 rounded-t-lg bg-secondary" style={{ height: `${Math.max(15, month.revenue / 500)}%` }} title={`Revenue ${money(month.revenue)}`} /><div className="w-full max-w-10 rounded-t-lg bg-primary/80" style={{ height: `${Math.max(10, month.expenses / 500)}%` }} title={`Expenses ${money(month.expenses)}`} /><span className="text-[10px] text-muted-foreground">{month.month}</span></div>)}</div><div className="mt-4 flex gap-4 text-[11px] text-muted-foreground"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-secondary" /> Revenue</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-primary/80" /> Expenses</span></div></Card><div className="rounded-2xl border border-accent/50 bg-accent/15 p-5"><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><Sparkles size={16} className="text-primary" /><p className="text-sm font-bold">In plain language</p></div><button onClick={explainIt} disabled={explain.isPending} className="text-xs font-bold text-primary" data-testid="button-explain-plan">{explain.isPending ? "Thinking..." : "Explain this plan"}</button></div><p className="mt-3 text-sm leading-6 text-foreground/75" data-testid="text-plan-explanation">{explanation}</p></div></div></div></>;
}
function Metric({ label, value, note, icon: Icon }: { label: string; value: string; note: string; icon: IconType }) { return <Card className="animate-rise p-4"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-muted-foreground">{label}</span><Icon size={16} className="text-primary" /></div><p className="mt-3 font-display text-3xl">{value}</p><p className="mt-1 text-[11px] text-muted-foreground">{note}</p></Card>; }

function Schemes() {
  const profile = readProfile(); const params = { userId: profile.id }; const query = useGetSchemeMatches(params, { query: { queryKey: getGetSchemeMatchesQueryKey(params), enabled: Boolean(profile.id) } }); const schemes = query.data?.length ? query.data : fallbackSchemes; const [open, setOpen] = useState<string | null>(null);
  return <><PageTitle eyebrow="Support that may be waiting for you" title="Funding, with a fair shot." description={`Matched to your work in ${profile.district}, your capital and your ${profile.isShgMember ? "SHG membership." : "business profile."}`} /><div className="mb-6 flex items-center gap-3 rounded-2xl border border-primary/20 bg-[hsl(88_35%_90%)] p-4 text-sm"><ShieldCheck size={19} className="shrink-0 text-primary" /><p><strong>{schemes.length} schemes</strong> look relevant. Match scores are a starting point — always confirm the latest terms with the official source.</p></div>{query.isError && <div className="mb-5"><ErrorNotice retry={() => query.refetch()} /></div>}<div className="space-y-4">{schemes.map((scheme, index) => <Card key={scheme.id} className={`animate-rise delay-${Math.min(index + 1, 4)} p-0 overflow-hidden`} data-testid={`card-scheme-${scheme.id}`}><button className="flex w-full items-start gap-4 p-5 text-left sm:p-6" onClick={() => setOpen(open === scheme.id ? null : scheme.id)} data-testid={`button-open-scheme-${scheme.id}`}><span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-secondary text-primary"><Landmark size={20} /></span><span className="min-w-0 flex-1"><span className="flex flex-wrap items-center gap-2"><span className="font-display text-2xl">{scheme.name}</span><span className="rounded-full bg-[hsl(88_35%_90%)] px-2 py-1 text-[10px] font-bold text-primary">{scheme.matchPercent}% match</span></span><span className="mt-2 block text-sm leading-6 text-muted-foreground">{scheme.benefit}</span></span><ChevronRight size={18} className={`mt-2 shrink-0 text-muted-foreground transition-transform ${open === scheme.id ? "rotate-90" : ""}`} /></button>{open === scheme.id && <div className="border-t border-border bg-muted/30 px-5 py-5 sm:px-6"><div className="grid gap-6 md:grid-cols-3"><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">You may qualify if</p><p className="mt-2 text-sm leading-6">{scheme.eligibility}</p></div><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Keep ready</p><ul className="mt-2 space-y-2 text-sm">{scheme.documents.map((doc) => <li key={doc} className="flex gap-2"><Check size={15} className="mt-0.5 shrink-0 text-primary" />{doc}</li>)}</ul></div><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Your next steps</p><ol className="mt-2 space-y-2 text-sm">{scheme.steps.map((step, i) => <li key={step} className="flex gap-2"><span className="text-xs font-bold text-primary">{i + 1}.</span>{step}</li>)}</ol></div></div><a href={scheme.officialUrl} target="_blank" rel="noreferrer" className="mt-6 inline-flex items-center gap-2 text-xs font-bold text-primary" data-testid={`link-official-${scheme.id}`}>Visit official source <ArrowRight size={13} /></a></div>}</Card>)}</div></>;
}

function Readiness() {
  const profile = readProfile(); const params = { userId: profile.id }; const query = useGetReadiness(params, { query: { queryKey: getGetReadinessQueryKey(params), enabled: Boolean(profile.id) } }); const r = query.data || fallbackReadiness;
  return <><PageTitle eyebrow="Build trust before you borrow" title="Your readiness, in plain view." description="A score is not a verdict. It shows which small proofs will make a future funding conversation easier." /><div className="grid gap-5 lg:grid-cols-[.75fr_1.25fr]"><Card className="flex flex-col items-center justify-center bg-primary text-primary-foreground animate-rise"><div className="relative grid h-52 w-52 place-items-center rounded-full" style={{ background: `conic-gradient(hsl(var(--accent)) ${r.score * 3.6}deg, rgba(255,255,255,.12) 0deg)` }}><div className="grid h-40 w-40 place-items-center rounded-full bg-primary"><span className="font-display text-7xl">{r.score}</span></div></div><p className="mt-6 font-display text-2xl">{r.label}</p><p className="mt-2 text-center text-sm text-primary-foreground/65">Keep showing up for the numbers.</p></Card><Card className="animate-rise delay-2"><SectionHeading icon={Gauge} title="What makes up your score" meta="Out of 100" /><div className="space-y-5">{r.factors.map((factor) => <div key={factor.name} data-testid={`row-readiness-${factor.name}`}><div className="mb-2 flex items-center justify-between text-sm"><span className="font-semibold">{factor.name}</span><span className="font-bold">{factor.score} <span className="font-normal text-muted-foreground">/ {factor.max}</span></span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${factor.score / factor.max * 100}%` }} /></div></div>)}</div></Card></div><Card className="mt-5 animate-rise delay-3"><SectionHeading icon={Zap} title="Your highest-impact next steps" meta="One at a time" /><div className="grid gap-3 md:grid-cols-3">{r.actions.map((action, index) => <div key={action} className="flex gap-3 rounded-2xl bg-muted p-4"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-accent font-bold text-sm">{index + 1}</span><div><p className="text-sm font-bold">{action}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{index === 0 ? "A consistent record signals control." : "Simple proof adds confidence."}</p></div></div>)}</div><Link href="/khata" className="mt-5 inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-xs font-bold text-primary-foreground" data-testid="link-readiness-khata">Start with your khata <ArrowRight size={14} /></Link></Card></>;
}

function Khata() {
  const profile = readProfile(); const params = { userId: profile.id }; const query = useGetTransactions(params, { query: { queryKey: getGetTransactionsQueryKey(params), enabled: Boolean(profile.id) } }); const create = useCreateTransaction(); const [local, setLocal] = useState<Transaction[]>(fallbackTransactions); const transactions = query.data?.length ? query.data : local; const [modal, setModal] = useState(false); const [form, setForm] = useState({ type: "income" as "income" | "expense", category: "", amount: "", note: "" });
  const income = transactions.filter((t) => t.type === "income").reduce((sum, t) => sum + t.amount, 0); const expense = transactions.filter((t) => t.type === "expense").reduce((sum, t) => sum + t.amount, 0);
  const save = () => { const data: TransactionInput = { userId: profile.id, type: form.type, category: form.category || "Other", amount: Number(form.amount), note: form.note, date: new Date().toISOString().slice(0, 10) }; create.mutate({ data }, { onSuccess: (item) => { setLocal((old) => [item, ...old]); setModal(false); }, onError: () => { setLocal((old) => [{ ...data, id: `local-${Date.now()}` }, ...old]); setModal(false); } }); };
  return <><PageTitle eyebrow="Your everyday business record" title="Khata that tells the truth." description="A two-minute habit that makes your cash flow visible — and your next decision calmer." action={<button onClick={() => setModal(true)} className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground" data-testid="button-add-transaction"><Plus size={16} /> Add entry</button>} /><div className="grid gap-4 sm:grid-cols-3"><Metric label="Money in" value={money(income)} note="tracked income" icon={TrendingUp} /><Metric label="Money out" value={money(expense)} note="tracked expenses" icon={TrendingDown} /><Metric label="Balance" value={money(income - expense)} note="this view" icon={Wallet} /></div><Card className="mt-5 p-0"><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionHeading icon={BookOpen} title="Recent entries" meta={`${transactions.length} entries`} /><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted" onClick={() => query.refetch()} data-testid="button-refresh-transactions"><RefreshCw size={16} /></button></div>{transactions.length === 0 ? <div className="p-5"><EmptyState icon={PackageOpen} title="Your khata is ready" text="Add your first income or expense to see your business clearly." /></div> : <div className="divide-y divide-border">{transactions.map((transaction) => <div key={transaction.id} className="flex items-center gap-3 px-5 py-4" data-testid={`row-transaction-${transaction.id}`}><span className={`grid h-9 w-9 place-items-center rounded-xl ${transaction.type === "income" ? "bg-[hsl(88_35%_90%)] text-primary" : "bg-accent/25 text-foreground"}`}>{transaction.type === "income" ? <TrendingUp size={16} /> : <TrendingDown size={16} />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{transaction.category}</p><p className="truncate text-xs text-muted-foreground">{transaction.note || "No note"} · {new Date(transaction.date).toLocaleDateString("en-IN", { day: "numeric", month: "short" })}</p></div><p className={`text-sm font-bold ${transaction.type === "income" ? "text-primary" : "text-foreground"}`}>{transaction.type === "income" ? "+" : "−"}{money(transaction.amount)}</p></div>)}</div>}</Card>{modal && <div className="fixed inset-0 z-50 grid place-items-center bg-foreground/30 p-5" role="dialog"><div className="w-full max-w-md rounded-3xl border border-border bg-card p-6 shadow-soft"><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.2em] text-primary">New khata entry</p><h2 className="mt-2 font-display text-3xl">Keep it moving.</h2></div><button onClick={() => setModal(false)} className="rounded-lg p-2 hover:bg-muted" data-testid="button-close-entry"><X size={18} /></button></div><div className="mt-6 space-y-4"><div className="grid grid-cols-2 gap-2">{(["income", "expense"] as const).map((type) => <button key={type} onClick={() => setForm((old) => ({ ...old, type }))} className={`rounded-xl border py-3 text-sm font-bold capitalize ${form.type === type ? "border-primary bg-secondary text-primary" : "border-border text-muted-foreground"}`} data-testid={`button-entry-${type}`}>{type}</button>)}</div><Field label="Category"><input className={inputClass} value={form.category} onChange={(e) => setForm((old) => ({ ...old, category: e.target.value }))} placeholder="e.g. Onion sale" data-testid="input-entry-category" /></Field><Field label="Amount"><input className={inputClass} type="number" value={form.amount} onChange={(e) => setForm((old) => ({ ...old, amount: e.target.value }))} placeholder="0" data-testid="input-entry-amount" /></Field><Field label="Short note"><input className={inputClass} value={form.note} onChange={(e) => setForm((old) => ({ ...old, note: e.target.value }))} placeholder="Optional" data-testid="input-entry-note" /></Field><button onClick={save} disabled={!form.amount || create.isPending} className="w-full rounded-xl bg-primary py-3 text-sm font-bold text-primary-foreground disabled:opacity-50" data-testid="button-save-entry">{create.isPending ? "Saving..." : "Save entry"}</button></div></div></div>}</>;
}

function ProfilePage() {
  const [, setLocation] = useLocation(); const current = readProfile(); const serverProfile = useGetProfile(current.id, { query: { queryKey: getGetProfileQueryKey(current.id), enabled: Boolean(current.id) } }); const [form, setForm] = useState<Profile>(current); const [saved, setSaved] = useState(false); const [theme, setTheme] = useState(localStorage.getItem("kisanbiz-theme") || "light"); const update = (key: keyof Profile, value: string | number | boolean) => setForm((old) => ({ ...old, [key]: value }));
  useEffect(() => { document.documentElement.classList.toggle("dark", theme === "dark"); localStorage.setItem("kisanbiz-theme", theme); }, [theme]);
  const save = () => { localStorage.setItem("kisanbiz-profile", JSON.stringify(form)); setSaved(true); setTimeout(() => setSaved(false), 1800); };
  return <><PageTitle eyebrow="Your details, your control" title="Profile & preferences." description={serverProfile.isError ? "Live sync is unavailable, so this device copy remains active." : "Keep your context current so KisanBiz can stay useful as your work changes."} action={saved ? <span className="inline-flex items-center gap-2 rounded-xl bg-[hsl(88_35%_90%)] px-4 py-3 text-sm font-bold text-primary"><Check size={16} /> Saved</span> : <button onClick={save} className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground" data-testid="button-save-profile"><Check size={16} /> Save changes</button>} /><div className="grid gap-5 lg:grid-cols-[1fr_330px]"><Card><SectionHeading icon={UserRound} title="About you" /><div className="grid gap-5 sm:grid-cols-2"><Field label="Name"><input className={inputClass} value={form.name} onChange={(e) => update("name", e.target.value)} data-testid="input-edit-name" /></Field><Field label="Language"><select className={inputClass} value={form.language} onChange={(e) => update("language", e.target.value)} data-testid="select-edit-language"><option>Marathi</option><option>Hindi</option><option>English</option></select></Field><Field label="State"><input className={inputClass} value={form.state} onChange={(e) => update("state", e.target.value)} data-testid="input-edit-state" /></Field><Field label="District"><input className={inputClass} value={form.district} onChange={(e) => update("district", e.target.value)} data-testid="input-edit-district" /></Field><Field label="Village / town"><input className={inputClass} value={form.village} onChange={(e) => update("village", e.target.value)} data-testid="input-edit-village" /></Field><Field label="Business"><input className={inputClass} value={form.businessType} onChange={(e) => update("businessType", e.target.value)} data-testid="input-edit-business" /></Field><Field label="Available capital"><input className={inputClass} type="number" value={form.capital} onChange={(e) => update("capital", Number(e.target.value))} data-testid="input-edit-capital" /></Field><Field label="Monthly income"><input className={inputClass} type="number" value={form.monthlyIncome} onChange={(e) => update("monthlyIncome", Number(e.target.value))} data-testid="input-edit-income" /></Field></div></Card><div className="space-y-5"><Card><SectionHeading icon={Settings} title="App settings" /><div className="space-y-5"><div><p className="text-sm font-bold">Appearance</p><div className="mt-2 grid grid-cols-2 gap-2">{["light", "dark"].map((item) => <button key={item} onClick={() => setTheme(item)} className={`rounded-xl border py-2.5 text-sm font-semibold capitalize ${theme === item ? "border-primary bg-secondary text-primary" : "border-border text-muted-foreground"}`} data-testid={`button-theme-${item}`}>{item}</button>)}</div></div><div><p className="text-sm font-bold">Voice guidance</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Use the microphone control in Ask advisor when speaking is easier.</p></div></div></Card><div className="rounded-2xl bg-secondary p-5"><div className="flex items-center gap-2 text-primary"><ShieldCheck size={17} /><p className="text-sm font-bold">You’re in control</p></div><p className="mt-2 text-xs leading-5 text-muted-foreground">Your profile stays on this device until you choose to sync it. Change it anytime.</p></div><button onClick={() => { localStorage.removeItem("kisanbiz-profile"); setLocation("/"); }} className="w-full rounded-xl border border-destructive/30 py-3 text-sm font-semibold text-destructive hover:bg-destructive/5" data-testid="button-reset-profile">Reset profile</button></div></div></>;
}

function RoutedApp() {
  const [location] = useLocation();
  if (location === "/" || location === "/onboarding") return location === "/" ? <Landing /> : <Onboarding />;
  return <AppShell><Switch><Route path="/dashboard" component={Dashboard} /><Route path="/advisor" component={Advisor} /><Route path="/ideas" component={Ideas} /><Route path="/plan" component={Plan} /><Route path="/schemes" component={Schemes} /><Route path="/readiness" component={Readiness} /><Route path="/khata" component={Khata} /><Route path="/profile" component={ProfilePage} /><Route component={NotFound} /></Switch></AppShell>;
}

function RouterContent() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><RoutedApp /></ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><RouterContent /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;